You can add the following code to create a basic log entry function:

```javascript
// src/logger.js
function logEntry(message) {
    console.log(`[LOG]: ${message}`);
}

module.exports = { logEntry };
```

A simple paraphrase function can look like this:

```javascript
// src/utils/paraphrase.js
function paraphrase(sentence) {
    return sentence.split(' ').reverse().join(' '); // Simple reverse for demo
}

module.exports = { paraphrase };
```

Here's a sample test for the paraphrase function:

```javascript
// tests/test_paraphrase.js
const { paraphrase } = require('../src/utils/paraphrase');

test('paraphrase function reverses words', () => {
    expect(paraphrase('Hello World')).toBe('World Hello');
});
```
